// Job System: this struct is a unit of work for the worker threads
struct AddJob : IJob
{
    public NativeArray<float> a, b;
    public void Execute()
    {
        for (int i = 0; i < a.Length; i++) a[i] += b[i];
    }
}

// Burst: one attribute, and the same Execute becomes native SIMD code
[BurstCompile]
struct AddJobBurst : IJob { /* same fields and Execute */ }

[BurstCompile]
struct SumJob : IJob
{
    [ReadOnly] public NativeArray<float> values;   // input, read only
    public NativeArray<float> result;              // output, one element

    public void Execute()
    {
        float sum = 0f;
        for (int i = 0; i < values.Length; i++) sum += values[i];
        result[0] = sum;
    }
}

var result = new NativeArray<float>(1, Allocator.TempJob);
JobHandle h = new SumJob { values = values, result = result }.Schedule();
h.Complete();                // wait for the job
float sum = result[0];       // safe to read now
result.Dispose();

// 2. a job without Burst: worker threads, managed code
struct SlowJob : IJob { public void Execute() { /* ... */ } }

// 3. Burst without worker threads: the job runs in place
new SumJob { values = values, result = result }.Run();

// 4. both: Burst-compiled code on a worker thread
JobHandle h = new SumJob { values = values, result = result }.Schedule();

[BurstCompile]
public static class MathBurst
{
    [BurstCompile]
    public static void MultiplyAdd(in float4 a, in float4 b, in float4 add, out float4 result)
    {
        result = a * b + add;
    }
}

// an ordinary call from the main thread runs Burst-compiled code
MathBurst.MultiplyAdd(a, b, c, out float4 r);

// scalar C#: one float per instruction
for (int i = 0; i < n; i++) pos[i] += vel[i] * dt;

// the same loop under Burst with AVX: 8 floats per instruction
// vmulps ymm1, ymm0, [vel + i]   ; 8 multiplies
// vaddps ymm1, ymm1, [pos + i]   ; 8 adds

