float big = 1e8f;
float a = (big + 1f) - big;   // 0: 1e8 + 1 rounds back to 1e8
float b = (big - big) + 1f;   // 1: the same numbers in another order

// a vectorized sum is 8 partial sums added up at the end: another order
// a * b + c as one FMA instruction: one rounding instead of two
// sin, exp, pow: each library and instruction set has its own approximation

// Strict: two roundings, round(round(a * b) + c)
float r1 = a * b + c;

// one rounding, round(a * b + c): more accurate, but different bits
// Fast may fuse r1 into an FMA too; math.mad says so explicitly:
// "with fast math on some architectures it could be converted to an FMA"
float r2 = math.mad(a, b, c);

