// 16.16 fixed point: the value times 65536, stored in an int
public struct Fix
{
    public int raw;
    public static Fix FromInt(int v) => new Fix { raw = v << 16 };
    public static Fix operator +(Fix a, Fix b) => new Fix { raw = a.raw + b.raw };
    public static Fix operator *(Fix a, Fix b)
        => new Fix { raw = (int)(((long)a.raw * b.raw) >> 16) };
}
