interface ISpeedRule { float Speed(float d, float v); }
List<ISpeedRule> rules;           // class objects, virtual calls
Func<float, float, float> rule;   // a delegate is a managed object too

// Burst: the simplest way is a data tag plus a switch
enum RuleKind : byte { Flee, Approach }
static float Speed(RuleKind k, float d, float v) => k switch
{
    RuleKind.Flee => v * 2f,
    _ => math.min(v, d),
};

[BurstCompile]                        // the containing type
public static class Rules
{
    // the "interface": a plain, non-generic delegate
    public delegate float SpeedRule(float distance, float baseSpeed);

    [BurstCompile]                    // the method itself
    [MonoPInvokeCallback(typeof(SpeedRule))]   // AOT namespace, for IL2CPP
    public static float Flee(float distance, float baseSpeed) => baseSpeed * 2f;

    [BurstCompile]
    [MonoPInvokeCallback(typeof(SpeedRule))]
    public static float Approach(float distance, float baseSpeed) =>
        math.min(baseSpeed, distance);
}

// once, from managed code (Awake or a static constructor), then cache it
FunctionPointer<Rules.SpeedRule> flee =
    BurstCompiler.CompileFunctionPointer<Rules.SpeedRule>(Rules.Flee);

[BurstCompile]
struct MoveJob : IJobParallelFor
{
    public FunctionPointer<Rules.SpeedRule> rule;   // just an address
    [ReadOnly] public NativeArray<float> distance;
    public NativeArray<float> speed;
    public float baseSpeed;

    public void Execute(int i) =>
        speed[i] = rule.Invoke(distance[i], baseSpeed);  // indirect call
}

// the level config picks the rule at runtime, the job stays the same
var job = new MoveJob { rule = level.panic ? flee : approach,
                        distance = distance, speed = speed, baseSpeed = 3f };
handle = job.Schedule(distance.Length, 64);

// one call per batch, not per element: the loop lives inside the pointer
public unsafe delegate void ScaleBatch(float* data, int count, float k);

[BurstCompile]
unsafe struct ScaleJob : IJobParallelForBatch   // Collections: Execute(start, count)
{
    public FunctionPointer<ScaleBatch> fn;
    public NativeArray<float> data;
    public float k;

    public void Execute(int start, int count)
    {
        float* p = (float*)data.GetUnsafePtr() + start;
        fn.Invoke(p, count, k);       // the overhead is paid once per batch
    }
}

