    public float k, limit;

    // no branch: math.select keeps the loop vectorizable (mulps, not mulss)
    public void Execute(int i) =>
        damped[i] = math.select(0f, speed[i] * k, speed[i] > limit);
}

// determinism, where it matters: [BurstCompile(FloatMode = FloatMode.Deterministic)]
// rule chosen at runtime: FunctionPointer<T>, in batches; known at compile time: MyJob<TRule>
// transforms: TransformAccessArray + IJobParallelForTransform, different roots
// physics: RaycastCommand.ScheduleBatch; first of all: the Profiler

[BurstCompile]
struct ClampJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> v;
    public NativeArray<float> r;
    public float k;
    public void Execute(int i)
    {
        if (v[i] > 0f) r[i] = v[i] * k;
        else r[i] = 0f;
    }
}

handle.Complete();
for (int i = 0; i < count; i++)
{
    for (int k = 0; k < maxHits; k++)
    {
        RaycastHit hit = results[i * maxHits + k];
        if (hit.collider == null) continue;
        Damage(hit.collider, hit.point);
    }
}

